
.clan-card {
  border: 1px solid var(--line-soft);
  border-left: 3px solid var(--text-dim);
  border-radius: 10px;
  overflow: hidden;
  background: rgba(236, 224, 194, 0.04);
  transition: border-color 0.25s ease;

  &.tend-green {
    border-left-color: var(--jade);
  }

  &.tend-red {
    border-left-color: var(--cinnabar);
  }

  &.tend-orange {
    border-left-color: #e0b04a;
  }
}

.clan-head {
  display: flex;
  align-items: center;
  gap: 6px;
  width: 100%;
  padding: 8px 10px;
  border: none;
  background: transparent;
  color: var(--parchment);
  font-family: inherit;
  font-size: 13px;
  cursor: pointer;
  text-align: left;

  &:active {
    background: rgba(255, 255, 255, 0.04);
  }
}

.clan-name {
  font-weight: bold;
  color: var(--gold-bright);
  letter-spacing: 1px;
  white-space: nowrap;
}

.clan-leader {
  white-space: nowrap;
  font-size: 12px;
}

.mini {
  flex: 1;
  min-width: 30px;
}

.power-num {
  font-variant-numeric: tabular-nums;
}

.tendency {
  font-size: 11px;
  white-space: nowrap;
  padding: 0 6px;
  border-radius: 3px;

  &.green {
    color: var(--jade);
    background: rgba(127, 209, 168, 0.1);
  }

  &.red {
    color: #ffb3a2;
    background: rgba(224, 138, 122, 0.1);
  }

  &.orange {
    color: #e0b04a;
    background: rgba(224, 176, 74, 0.1);
  }

  &.gray {
    color: var(--text-dim);
    background: rgba(236, 224, 194, 0.06);
  }
}

.star {
  font-size: 11px;
}

.chevron {
  color: var(--text-dim);
  font-size: 11px;
  transition: transform 0.25s ease;
}

.clan-detail {
  display: flex;
  flex-direction: column;
  gap: 4px;
  padding: 8px 10px 9px;
  border-top: 1px dashed var(--line-soft);
  background: rgba(0, 0, 0, 0.16);
}

.rel {
  color: var(--gold-bright);
}

.relative {
  margin-right: 7px;
}

.num {
  color: var(--parchment);
  font-variant-numeric: tabular-nums;
}

.talent {
  color: var(--gold-bright);
}

.recent {
  color: var(--jade);
}
