
.panel-content {
  display: flex;
  flex-direction: column;
  gap: 8px;
}

.realm {
  display: flex;
  flex-direction: column;
  gap: 7px;
  padding: 10px;
  background:
    radial-gradient(130% 100% at 50% 0%, rgba(200, 160, 74, 0.13), transparent 65%),
    rgba(236, 224, 194, 0.04);
  border: 1px solid var(--line-soft);
  border-radius: 11px;
}

.gains {
  gap: 5px;
}

.gain-chip {
  font-size: 11px;
  padding: 1px 7px;
  border-radius: 20px;
  color: var(--jade);
  border: 1px solid rgba(127, 209, 168, 0.3);
  background: rgba(127, 209, 168, 0.07);
}

.sandbox {
  display: flex;
  flex-direction: column;
  gap: 4px;
  padding: 7px 9px;
  border: 1px solid var(--line-soft);
  border-radius: 9px;
  background-image:
    linear-gradient(rgba(200, 160, 74, 0.07) 1px, transparent 1px),
    linear-gradient(90deg, rgba(200, 160, 74, 0.07) 1px, transparent 1px);
  background-size: 22px 22px;
}

.sandbox-row {
  display: flex;
  align-items: center;
  gap: 7px;
  flex-wrap: wrap;
}

.sb-label {
  color: var(--text-dim);
  font-size: 11.5px;
  letter-spacing: 1px;
}

.sb-value {
  color: var(--gold-bright);
  font-weight: bold;
  font-variant-numeric: tabular-nums;
  margin-right: 8px;
}

.pop-row {
  gap: 8px;
}

.pop-cell {
  font-size: 12px;
  color: var(--text-dim);

  b {
    color: var(--parchment);
    font-variant-numeric: tabular-nums;
  }
}

.bar {
  flex: 1;
  min-width: 60px;
}

.mini-bar {
  min-width: 40px;
  flex: none;
  width: 56px;
}

.sub-list {
  display: flex;
  flex-direction: column;
  gap: 6px;
}

.column {
  flex-direction: column;
  align-items: flex-start;
}

.bld-name {
  font-weight: bold;
  color: var(--parchment);
}

.bld-count {
  color: var(--jade);
  font-weight: bold;
  font-size: 12px;
}

.bld-level {
  font-size: 11px;
  color: var(--gold-bright);
  border: 1px solid var(--line-soft);
  border-radius: 3px;
  padding: 0 5px;
}

.special-item {
  border-color: rgba(200, 85, 61, 0.35);
  background: rgba(200, 85, 61, 0.06);
}

.special-name {
  color: #e8a48e;
}

.resource-grid {
  display: grid;
  grid-template-columns: repeat(4, 1fr);
  gap: 6px;
}

.resource-cell {
  display: flex;
  flex-direction: column;
  align-items: center;
  gap: 2px;
  padding: 7px 2px 6px;
  background: linear-gradient(180deg, rgba(236, 224, 194, 0.07), rgba(236, 224, 194, 0.03));
  border: 1px solid var(--line-soft);
  border-top: 2px solid rgba(200, 160, 74, 0.45);
  border-radius: 7px;
}

.resource-name {
  font-size: 11px;
  color: var(--text-dim);
  letter-spacing: 1px;
}

.resource-value {
  font-size: 15px;
  font-weight: bold;
  color: var(--gold-bright);
  font-variant-numeric: tabular-nums;
}

.law-item {
  border-left: 3px solid rgba(200, 85, 61, 0.5);
}

.law-name {
  color: var(--gold-bright);
  font-weight: bold;
}

.news {
  display: flex;
  flex-direction: column;
  gap: 6px;
  padding: 9px 10px;
  background:
    radial-gradient(120% 100% at 0% 0%, rgba(127, 209, 168, 0.1), transparent 55%),
    rgba(127, 209, 168, 0.04);
  border: 1px solid rgba(127, 209, 168, 0.22);
  border-radius: 10px;
}

.news-headline {
  display: flex;
  gap: 7px;
  align-items: flex-start;
  font-size: 12.5px;
  color: var(--parchment);
}

.news-local {
  display: flex;
  gap: 7px;
  align-items: flex-start;
  font-size: 12px;
  padding: 5px 8px;
  background: rgba(236, 224, 194, 0.05);
  border: 1px dashed var(--line-soft);
  border-radius: 7px;
}

.news-icon {
  flex: none;
}
