
.panel-content {
  display: flex;
  flex-direction: column;
  gap: 8px;
}

.seal i {
  font-size: 11px;
  margin-right: 3px;
}

.sub-list {
  display: flex;
  flex-direction: column;
  gap: 7px;
}

.goods {
  display: flex;
  flex-direction: column;
  gap: 4px;
  padding: 8px 10px;
  background:
    radial-gradient(120% 100% at 100% 0%, rgba(200, 160, 74, 0.1), transparent 60%),
    rgba(236, 224, 194, 0.04);
  border: 1px solid var(--line-soft);
  border-radius: 10px;
}

.goods-name {
  font-weight: bold;
  color: var(--gold-bright);
  letter-spacing: 1px;
}

.goods-price {
  margin-left: auto;
  color: var(--jade);
  font-weight: bold;
  font-variant-numeric: tabular-nums;

  i {
    color: var(--gold);
    font-size: 11px;
    margin-right: 3px;
  }
}

.goods-stock {
  font-size: 11px;
  color: var(--text-dim);
}

.tip {
  color: var(--text-dim);
  border-top: 1px dashed var(--line-soft);
  padding-top: 6px;
}
