
.panel-content {
  display: flex;
  flex-direction: column;
  gap: 8px;
}

.identity {
  display: flex;
  flex-direction: column;
  gap: 3px;
}

.name {
  font-size: 17px;
  font-weight: bold;
  color: var(--gold-bright);
  letter-spacing: 2px;
  text-shadow: 0 1px 3px rgba(0, 0, 0, 0.5);
}

.age {
  font-size: 13px;
}

.id-tag {
  font-size: 11.5px;
  color: var(--text-dim);
  background: rgba(236, 224, 194, 0.06);
  border: 1px solid var(--line-soft);
  border-radius: 4px;
  padding: 1px 7px;
}

.state {
  font-style: italic;
  color: var(--text-dim);
}

.level-box {
  display: flex;
  flex-direction: column;
  gap: 6px;
  padding: 9px 10px;
  background: linear-gradient(135deg, rgba(200, 160, 74, 0.09), rgba(200, 160, 74, 0.02));
  border: 1px solid var(--line-soft);
  border-radius: 10px;
}

.points {
  margin-left: auto;
  display: inline-flex;
  align-items: center;
  gap: 5px;
  color: var(--jade);
  font-weight: bold;
  font-size: 13px;

  i {
    color: var(--gold);
    font-size: 12px;
  }
}

.exp {
  flex: 1;
  min-width: 60px;
}

.exp-label {
  letter-spacing: 2px;
}

.exp-num {
  font-variant-numeric: tabular-nums;
  color: var(--gold-bright);
}

.sub-list {
  display: flex;
  flex-direction: column;
  gap: 6px;
}

.bag-item {
  align-items: flex-start;
}

.bag-name {
  font-weight: bold;
  color: var(--parchment);
}

.bag-count {
  color: var(--jade);
  font-weight: bold;
  font-variant-numeric: tabular-nums;
  font-size: 12px;
}

.bag-desc {
  flex-basis: 100%;
}

.column {
  flex-direction: column;
  align-items: flex-start;
}

.wife-name {
  color: var(--cinnabar);
  font-weight: bold;
}

.child {
  margin-right: 7px;
}
