
.panel-content {
  display: flex;
  flex-direction: column;
  gap: 8px;
}

.military-box {
  display: flex;
  flex-direction: column;
  gap: 7px;
  padding: 10px;
  background:
    radial-gradient(130% 100% at 50% 0%, rgba(200, 85, 61, 0.12), transparent 65%),
    rgba(236, 224, 194, 0.04);
  border: 1px solid var(--line-soft);
  border-radius: 11px;
}

.chariots {
  display: flex;
  align-items: center;
  gap: 4px;
  flex-wrap: wrap;
  padding: 7px 9px;
  border: 1px dashed rgba(200, 160, 74, 0.3);
  border-radius: 9px;
  background: rgba(0, 0, 0, 0.2);
}

.chariot {
  color: var(--gold);
  font-size: 15px;
  filter: drop-shadow(0 0 4px rgba(200, 160, 74, 0.5));
}

.military-meta {
  color: var(--text-dim);

  .dot {
    color: var(--gold-deep);
  }
}

.sub-list {
  display: flex;
  flex-direction: column;
  gap: 6px;
}

.general-name {
  font-weight: bold;
  color: var(--gold-bright);
}

.loyalty {
  margin-left: auto;
  font-size: 11.5px;
  color: var(--jade);
}
