
.panel-content {
  display: flex;
  flex-direction: column;
  gap: 8px;
}

.clan-box {
  display: flex;
  flex-direction: column;
  gap: 5px;
  padding: 10px;
  background:
    radial-gradient(130% 100% at 50% 0%, rgba(200, 160, 74, 0.13), transparent 65%),
    rgba(236, 224, 194, 0.04);
  border: 1px solid var(--line-soft);
  border-radius: 11px;
}

.genealogy {
  i {
    color: var(--gold);
    margin-right: 4px;
  }
}

.rest-count {
  font-weight: normal;
  color: var(--text-dim);
  letter-spacing: 0;
}

.clan-item {
  display: contents;
}

.sub-list {
  display: flex;
  flex-direction: column;
  gap: 6px;
}

.column {
  flex-direction: column;
  align-items: flex-start;
}

.dead-item {
  border-left: 3px solid rgba(200, 85, 61, 0.55);
  background: rgba(200, 85, 61, 0.05);
}

.dead-name {
  color: #e8a48e;
  font-weight: bold;
}

.remnant {
  color: var(--gold-bright);
}

.dynamic-item {
  display: flex;
  gap: 7px;
  align-items: flex-start;
  font-size: 12px;
  color: var(--text-dim);
}

.dyn-dot {
  flex: none;
  width: 5px;
  height: 5px;
  border-radius: 50%;
  background: var(--gold);
  margin-top: 6px;
}
